import requests,concurrent.futures,io,zipfile,subprocess
from pathlib import Path
from lxml import html,etree
base=Path('audit/flora_blind_2026-10/texts/2736b815e9f115a4')
ls=[]
for page in [1,2]:
 j=requests.get(f'https://api.osf.io/v2/nodes/xwn9m/files/github/reports/?page={page}&page[size]=100',timeout=10).json()
 ls += [d for d in j['data'] if d['attributes']['kind']=='file']
def fetch(d):
 name=d['attributes']['name'];url=d['links']['download']
 try:
  r=requests.get(url,timeout=12);r.raise_for_status()
  if name.endswith('.html'):
   root=html.fromstring(r.content)
   for x in root.xpath('//script|//style'): x.drop_tree()
   s=root.text_content()
  elif name.endswith('.docx'):
   root=etree.fromstring(zipfile.ZipFile(io.BytesIO(r.content)).read('word/document.xml'));s='\n'.join(''.join(x.itertext()) for x in root.findall('.//{*}p'))
  else:
   p=Path(str(base)+'.'+name+'.tmp');p.write_bytes(r.content)
   z=subprocess.run(['pdftotext',str(p),'-'],capture_output=True);s=z.stdout.decode();p.unlink()
  return {'name':name,'url':r.url,'text':s}
 except Exception as e: return {'name':name,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex: out=list(ex.map(fetch,ls))
import json
Path(str(base)+'.reports.tmp').write_text(json.dumps(out,ensure_ascii=False))
print('reports',len(out),'parsed',sum('text'in x for x in out))
for x in out:
 if x['name'].split('.')[0] in ['austerweil2011','child2018','li2020','otto2014','okan2018','peer2022','schechtman2010','sofer2015','wal2021','zaval2015','dale2011']:
  s=x.get('text','');import re
  hits=list(re.finditer('Discussion|discussion|Summary|summary',s));pos=hits[-1].start() if hits else max(0,len(s)-5000)
  print('\nFILE',x['name'],'\n',s[pos:pos+5500])
